    "parameters": {
        "type": "object",
        "properties": {
            "job_id": _JOB_ID,
            "stream": {"type": "string", "enum": ["stdout", "stderr"], "default": "stderr"},
            "tail_lines": {"type": "integer", "description": "Number of lines from the end (1-200)", "default": 20},
        },
        "required": ["job_id"],
